        lines.append("")
        for conn in ir.connections:
            arrow = "..>" if conn.kind in ("deploy", "manifest") else "-->"
            line = f"{conn.from_} {arrow} {conn.to}"
            if conn.text:
                line += f" : {conn.text}"
            lines.append(line)
        lines.append("@enduml")
        return "\n".join(lines)

